using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using UsedCarSales.Api.Data; using UsedCarSales.Api.Models;
namespace UsedCarSales.Api.Controllers;
[ApiController, Route("api/[controller]")] public class CustomersController(AppDbContext db) : ControllerBase { [HttpGet] public async Task<IActionResult> GetAll([FromQuery]string? search) { var q=db.Customers.AsNoTracking().AsQueryable(); if(!string.IsNullOrWhiteSpace(search))q=q.Where(c=>c.FullName.Contains(search)||c.Phone.Contains(search)||c.Email.Contains(search)); return Ok(await q.OrderBy(c=>c.FullName).ToListAsync()); } [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id) { var c=await db.Customers.FindAsync(id); return c is null?NotFound():Ok(c); } [HttpPost] public async Task<IActionResult> Create(Customer c) { c.Id=0; db.Customers.Add(c); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Get),new{id=c.Id},c); } [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,Customer input) { var c=await db.Customers.FindAsync(id); if(c is null)return NotFound(); c.FullName=input.FullName; c.Phone=input.Phone; c.Email=input.Email; c.Address=input.Address; await db.SaveChangesAsync(); return Ok(c); } [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id) { var c=await db.Customers.FirstOrDefaultAsync(x=>x.Id==id); if(c is null)return NotFound(); if(await db.Sales.AnyAsync(s=>s.CustomerId==id))return BadRequest("Customers with sales history cannot be deleted."); db.Customers.Remove(c); await db.SaveChangesAsync(); return NoContent(); } }
